CREATE TABLE commerce_payments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,inquiry_id TEXT NOT NULL,customer_id TEXT NOT NULL,amount_centimes INTEGER NOT NULL CHECK(amount_centimes BETWEEN 0 AND 10000000),eligible_centimes INTEGER NOT NULL CHECK(eligible_centimes BETWEEN 0 AND amount_centimes),redeemed_centimes INTEGER NOT NULL CHECK(redeemed_centimes BETWEEN 0 AND 10000000 AND amount_centimes+redeemed_centimes>0),earned_centimes INTEGER NOT NULL CHECK(earned_centimes>=0),rate_bps INTEGER NOT NULL CHECK(rate_bps IN (0,100,200)),expiry_days INTEGER NOT NULL,verification TEXT NOT NULL DEFAULT 'merchant_reported' CHECK(verification='merchant_reported'),authorization TEXT NOT NULL CHECK(authorization IN ('none','in_person_verified')),actor TEXT NOT NULL,receipt_reference TEXT,tenant_revision INTEGER NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,inquiry_id) REFERENCES inquiries(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TABLE commerce_refunds(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,payment_id TEXT NOT NULL,cash_centimes INTEGER NOT NULL CHECK(cash_centimes>=0),credit_centimes INTEGER NOT NULL CHECK(credit_centimes>=0 AND cash_centimes+credit_centimes>0),reason TEXT NOT NULL,actor TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,payment_id) REFERENCES commerce_payments(tenant_id,id));
CREATE TRIGGER commerce_payment_guard BEFORE INSERT ON commerce_payments BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inquiries b JOIN tenants t ON t.id=b.tenant_id WHERE b.tenant_id=NEW.tenant_id AND b.id=NEW.inquiry_id AND b.customer_id=NEW.customer_id AND b.status='fulfilled' AND t.revision=NEW.tenant_revision AND NEW.rate_bps=t.loyalty_bps AND NEW.expiry_days=t.loyalty_expiry_days AND NEW.earned_centimes=MIN(NEW.eligible_centimes*t.loyalty_bps/10000,t.loyalty_cap)) THEN RAISE(ABORT,'invalid_payment') END; SELECT CASE WHEN NEW.amount_centimes+NEW.redeemed_centimes+COALESCE((SELECT SUM(amount_centimes+redeemed_centimes) FROM commerce_payments WHERE tenant_id=NEW.tenant_id AND inquiry_id=NEW.inquiry_id),0)-COALESCE((SELECT SUM(r.cash_centimes+r.credit_centimes) FROM commerce_refunds r JOIN commerce_payments p ON p.tenant_id=r.tenant_id AND p.id=r.payment_id WHERE p.tenant_id=NEW.tenant_id AND p.inquiry_id=NEW.inquiry_id),0)>(SELECT price_centimes FROM inquiries WHERE tenant_id=NEW.tenant_id AND id=NEW.inquiry_id) THEN RAISE(ABORT,'payment_exceeds_invoice') END; SELECT CASE WHEN NEW.redeemed_centimes>0 AND (NEW.authorization!='in_person_verified' OR NEW.redeemed_centimes<(SELECT loyalty_min_redeem FROM tenants WHERE id=NEW.tenant_id) OR NEW.redeemed_centimes>COALESCE((SELECT balance_centimes FROM loyalty_balances WHERE tenant_id=NEW.tenant_id AND customer_id=NEW.customer_id),0) OR NEW.redeemed_centimes>COALESCE((SELECT SUM(MAX(0,remaining)) FROM loyalty_lots WHERE tenant_id=NEW.tenant_id AND customer_id=NEW.customer_id AND (expires_at IS NULL OR expires_at>NEW.created_at)),0)) THEN RAISE(ABORT,'insufficient_credit_or_authority') END; END;
CREATE TRIGGER commerce_payment_ledger AFTER INSERT ON commerce_payments BEGIN INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,event_key,created_at) SELECT 'commerce-redeem:'||NEW.id,NEW.tenant_id,NEW.customer_id,NULL,'redeem',-NEW.redeemed_centimes,'commerce-redeem:'||NEW.id,NEW.created_at WHERE NEW.redeemed_centimes>0; INSERT INTO loyalty_allocations SELECT NEW.tenant_id,'commerce-redeem:'||NEW.id,id,MIN(remaining,NEW.redeemed_centimes-previous) FROM (SELECT id,remaining,COALESCE(SUM(remaining) OVER (ORDER BY created_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) previous FROM loyalty_lots WHERE tenant_id=NEW.tenant_id AND customer_id=NEW.customer_id AND remaining>0 AND (expires_at IS NULL OR expires_at>NEW.created_at)) WHERE previous<NEW.redeemed_centimes; INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,event_key,expires_at,created_at) SELECT 'commerce-earn:'||NEW.id,NEW.tenant_id,NEW.customer_id,NULL,'earn',NEW.earned_centimes,'commerce-earn:'||NEW.id,CASE WHEN NEW.expiry_days>0 THEN NEW.created_at+NEW.expiry_days*86400000 ELSE NULL END,NEW.created_at WHERE NEW.earned_centimes>0; END;
CREATE TRIGGER commerce_refund_guard BEFORE INSERT ON commerce_refunds BEGIN SELECT CASE WHEN NEW.cash_centimes+COALESCE((SELECT SUM(cash_centimes) FROM commerce_refunds WHERE tenant_id=NEW.tenant_id AND payment_id=NEW.payment_id),0)>(SELECT amount_centimes FROM commerce_payments WHERE tenant_id=NEW.tenant_id AND id=NEW.payment_id) OR NEW.credit_centimes+COALESCE((SELECT SUM(credit_centimes) FROM commerce_refunds WHERE tenant_id=NEW.tenant_id AND payment_id=NEW.payment_id),0)>(SELECT redeemed_centimes FROM commerce_payments WHERE tenant_id=NEW.tenant_id AND id=NEW.payment_id) THEN RAISE(ABORT,'refund_exceeds_payment') END; END;
CREATE TRIGGER commerce_refund_ledger AFTER INSERT ON commerce_refunds BEGIN INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,reference_id,event_key,created_at) SELECT 'commerce-reversal:'||NEW.id,NEW.tenant_id,p.customer_id,NULL,'reversal',-MAX(0,p.earned_centimes-((p.amount_centimes-(SELECT SUM(cash_centimes) FROM commerce_refunds WHERE tenant_id=p.tenant_id AND payment_id=p.id))*p.earned_centimes/MAX(1,p.amount_centimes))+COALESCE((SELECT SUM(amount_centimes) FROM loyalty_ledger WHERE tenant_id=p.tenant_id AND reference_id='commerce-earn:'||p.id),0)),'commerce-earn:'||p.id,'commerce-reversal:'||NEW.id,NEW.created_at FROM commerce_payments p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.payment_id AND p.earned_centimes>0; INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,event_key,expires_at,created_at) SELECT 'commerce-restore:'||NEW.id,NEW.tenant_id,p.customer_id,NULL,'restore',NEW.credit_centimes,'commerce-restore:'||NEW.id,CASE WHEN p.expiry_days>0 THEN NEW.created_at+p.expiry_days*86400000 ELSE NULL END,NEW.created_at FROM commerce_payments p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.payment_id AND NEW.credit_centimes>0; END;
CREATE TRIGGER commerce_payments_no_update BEFORE UPDATE ON commerce_payments BEGIN SELECT RAISE(ABORT,'append_only_payment'); END;
CREATE TRIGGER commerce_payments_no_delete BEFORE DELETE ON commerce_payments BEGIN SELECT RAISE(ABORT,'append_only_payment'); END;
CREATE TRIGGER commerce_refunds_no_update BEFORE UPDATE ON commerce_refunds BEGIN SELECT RAISE(ABORT,'append_only_refund'); END;
CREATE TRIGGER commerce_refunds_no_delete BEFORE DELETE ON commerce_refunds BEGIN SELECT RAISE(ABORT,'append_only_refund'); END;
CREATE TRIGGER commerce_payment_event AFTER INSERT ON commerce_payments BEGIN INSERT INTO launch_events VALUES ('commerce-payment:'||NEW.id,NEW.tenant_id,'merchant_payment_recorded','commerce-payment:'||NEW.id,NEW.created_at); END;
CREATE TRIGGER loyalty_terms_guard BEFORE UPDATE OF loyalty_bps ON tenants WHEN NEW.loyalty_bps>0 AND NEW.onboarding_started_at IS NOT NULL AND NEW.loyalty_terms_accepted_at IS NULL BEGIN SELECT RAISE(ABORT,'loyalty_terms_required'); END;
CREATE TABLE support_interventions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),minutes INTEGER NOT NULL CHECK(minutes BETWEEN 0 AND 10080),reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE plan_definitions(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,monthly_price_centimes INTEGER CHECK(monthly_price_centimes>=0),currency TEXT NOT NULL DEFAULT 'MAD',collection TEXT NOT NULL DEFAULT 'disabled' CHECK(collection='disabled'));
CREATE TABLE plan_quotas(plan_id TEXT NOT NULL REFERENCES plan_definitions(id),feature TEXT NOT NULL,maximum INTEGER NOT NULL CHECK(maximum>=0),PRIMARY KEY(plan_id,feature));
INSERT INTO plan_definitions(id,display_name) VALUES ('pilot','Offre pilote — conditions à définir');
INSERT INTO plan_quotas VALUES ('pilot','catalog_items',100),('pilot','services',40),('pilot','assets',10);
CREATE TRIGGER catalog_plan_quota BEFORE INSERT ON catalog_items BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM catalog_items WHERE tenant_id=NEW.tenant_id)>=(SELECT q.maximum FROM tenant_subscription_status s JOIN plan_quotas q ON q.plan_id=s.plan WHERE s.tenant_id=NEW.tenant_id AND q.feature='catalog_items') THEN RAISE(ABORT,'plan_quota') END; END;
CREATE TRIGGER service_plan_quota BEFORE INSERT ON services BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM services WHERE tenant_id=NEW.tenant_id)>=(SELECT q.maximum FROM tenant_subscription_status s JOIN plan_quotas q ON q.plan_id=s.plan WHERE s.tenant_id=NEW.tenant_id AND q.feature='services') THEN RAISE(ABORT,'plan_quota') END; END;
